    """Write a function that returns true if the given number is the multiplication of 3 prime numbers
    and false otherwise.
    Knowing that (a) is less then 100. 
    Example:
    is_multiply_prime(30) == True
    30 = 2 * 3 * 5
    """
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    factors = []
    i = 2
    temp = a
    while i * i <= temp:
        if temp % i == 0:
            if is_prime(i):
                factors.append(i)
                temp //= i
            else:
                i += 1
                continue
        else:
            i += 1
    if temp > 1:
        if is_prime(temp):
            factors.append(temp)

    if len(factors) == 3:
        return True
    else:
        return False
