    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}

    """
    letter_counts = {}
    words = test.split()
    for word in words:
        letter_counts[word] = letter_counts.get(word, 0) + 1

    if not letter_counts:
        return {}

    max_count = max(letter_counts.values())

    result = {}
    for letter, count in letter_counts.items():
        if count == max_count:
            result[letter] = count

    return result
