    for char in string:
        if char == '[':
            stack.append(char)
        elif char == ']':
            if stack:
                stack.pop()
            else:
                return False
    if not stack:
        return False

    count = 0
    for i in range(len(string) - 1):
        if string[i] == '[' and string[i+1] == ']':
